def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    # find horizontal strips (runs of length >= 2)
    strips = []
    in_strip = np.zeros_like(g, dtype=bool)
    for y in range(H):
        x = 0
        while x < W:
            if g[y, x] != bg:
                x0 = x
                while x < W and g[y, x] != bg:
                    x += 1
                if x - x0 >= 2:
                    strips.append([int(v) for v in g[y, x0:x]])
                    in_strip[y, x0:x] = True
            else:
                x += 1
    # stamp a strip at each lone pixel, aligned on its colour
    for y in range(H):
        for x in range(W):
            if g[y, x] != bg and not in_strip[y, x]:
                c = int(g[y, x])
                for s in strips:
                    if c in s:
                        i = s.index(c)
                        start = x - i
                        for k, v in enumerate(s):
                            xx = start + k
                            if 0 <= xx < W:
                                out[y, xx] = v
                        emit(out, f"Pixel {c} at ({y},{x}) expands into strip {s}, aligned so its {c} sits on the pixel")
                        break
    emit(out, "All lone pixels expanded into their palette strips")
    return out
